import { describe, it, expect, vi, beforeEach } from "vitest";
import { NextRequest } from "next/server";
import { prisma } from "@/lib/prisma";
import * as auth from "@/lib/auth";
import { PATCH as patchSession, POST as startSession } from "@/app/api/sessions/route";
import {
  clampSessionSeconds,
  clampSessionBreakSeconds,
  sessionDeltaSeconds,
  sessionMultiplierForSeconds,
  streakMultiplierForWeeks,
  canonicalSessionRewards,
  SESSION_GRACE_SECONDS,
} from "@/lib/session-math";

// Route tests exercise transport only. Durable settlement and weekly atomicity
// run against real PostgreSQL in the required Phase 1 suite.
vi.mock("@/lib/planner/v2/server/web", () => ({
  durablePlanner: () => ({ sessions: {
    settleLegacy: async (ownerId: number, request: { id: number; focus: number; breaks: number; questId?: number; complete: boolean; final: boolean }) => {
      const result = await prisma.$queryRaw<Array<{ settle_study_session_atomic: Record<string, unknown> }>>`
        SELECT public.settle_study_session_atomic(${ownerId},${request.id},${request.focus},${request.breaks},${request.questId ?? null},${null},${request.complete},${request.final},${new Date().toISOString().slice(0, 10)}) AS settle_study_session_atomic
      `;
      return { ...result[0].settle_study_session_atomic, weeklyAwarded: false };
    },
  } }),
}));

vi.mock("@/lib/auth", () => ({
  getSession: vi.fn(),
  verifyToken: vi.fn(),
  signToken: vi.fn().mockResolvedValue("mock-jwt-token"),
}));

/* ═══════════════════════════════════════════════════════════
   Core Invariant 1 — Exact Time Parity (seconds in == seconds out)
   ═══════════════════════════════════════════════════════════ */
describe("Session Duration Math — exact time parity", () => {
  it("clamps claimed duration against wall-clock elapsed + grace window", () => {
    const now = 1_000_000_000_000; // fixed server now

    // Claimed 2 hours, but the session started 10 minutes ago → 660s max
    const started10m = now - 10 * 60_000;
    expect(clampSessionSeconds(7200, started10m, now)).toBe(600 + SESSION_GRACE_SECONDS);

    // Claimed 1 hour, started 20 minutes ago → 1200 + 60 = 1260s
    const started20m = now - 20 * 60_000;
    expect(clampSessionSeconds(3600, started20m, now)).toBe(1260);

    // Honest claim stays untouched
    expect(clampSessionSeconds(120, now - 300_000, now)).toBe(120);

    // Negative / garbage claims floor at 0
    expect(clampSessionSeconds(-500, now - 60_000, now)).toBe(0);
  });

  it("credits repeated cumulative flushes as exact deltas (no inflation)", () => {
    // A 3-hour session flushed every 180s (like the live client) sends
    // cumulative durations: 180, 360, 540, ... 10800.
    let previous = 0;
    let credited = 0;
    for (let cum = 180; cum <= 10800; cum += 180) {
      const delta = sessionDeltaSeconds(previous, cum);
      credited += delta;
      previous = cum;
    }
    expect(credited).toBe(10800); // 3 hours exactly — NOT 91 hours
    expect(previous).toBe(10800);
  });

  it("a 120-second session records exactly 120 seconds and 2 minutes", () => {
    expect(sessionDeltaSeconds(0, 120)).toBe(120);
    expect(Math.floor(clampSessionSeconds(120, Date.now() - 130_000) / 60)).toBe(2);
  });

  it("clamps break time so focus + break never exceed the wall-clock window", () => {
    const now = 1_000_000_000_000; // fixed server now
    const started5hAgo = now - 5 * 3_600_000; // 12pm → 5pm window

    // Honest 3h focus + 2h break inside a 5h window → break passes untouched.
    expect(clampSessionBreakSeconds(7200, started5hAgo, 10800, now)).toBe(7200);

    // Spoofed 20h break on a 5h session with 3h focus →
    // budget = 5h + grace − 3h focus = 7260s.
    expect(clampSessionBreakSeconds(72000, started5hAgo, 10800, now)).toBe(7200 + SESSION_GRACE_SECONDS);

    // Garbage / negative claims floor at 0.
    expect(clampSessionBreakSeconds(-5, started5hAgo, 10800, now)).toBe(0);

    // Break beyond the wall-clock window with no grace room → capped at 0.
    const started10m = now - 10 * 60_000;
    expect(clampSessionBreakSeconds(600, started10m, 600 + SESSION_GRACE_SECONDS, now)).toBe(0);
  });
});

/* ═══════════════════════════════════════════════════════════
   Core Invariant 2 — Canonical Reward Parity
   XP = floor(5 × minutes × xpMultiplier)
   Sylph = max(5, floor(0.5 × minutes × sylphMultiplier))
   ═══════════════════════════════════════════════════════════ */
describe("Canonical Session Rewards", () => {
  it("120s (2 min) session → exactly 2-minute XP and minimum Sylph", () => {
    const r = canonicalSessionRewards(120, 0);
    expect(r.minutes).toBe(2);
    expect(r.xp).toBe(Math.floor(5 * 2 * 1.0)); // 10 XP
    expect(r.sylph).toBe(Math.max(5, Math.floor(0.5 * 2 * 1.0))); // 5 Sylph
  });

  it("3-hour session → canonical single-shot payout from FULL duration", () => {
    const r = canonicalSessionRewards(10800, 0); // 180 minutes
    expect(r.sessionMultiplier).toBe(1.3);
    expect(r.xp).toBe(Math.floor(5 * 180 * 1.3)); // 1170 XP — not per-flush repeats
    expect(r.sylph).toBe(Math.floor(0.5 * 180 * 1.0)); // 90 Sylph
  });

  it("30-minute session applies the 1.1x multiplier", () => {
    const r = canonicalSessionRewards(1800, 0);
    expect(r.sessionMultiplier).toBe(1.1);
    expect(r.xp).toBe(Math.floor(5 * 30 * 1.1)); // 165 XP
    expect(r.sylph).toBe(15); // 0.5 × 30
  });

  it("applies the weekly-streak sylphMultiplier ladder", () => {
    expect(streakMultiplierForWeeks(0)).toBe(1.0);
    expect(streakMultiplierForWeeks(1)).toBe(1.05);
    expect(streakMultiplierForWeeks(2)).toBe(1.15);
    expect(streakMultiplierForWeeks(4)).toBe(1.3);
    expect(streakMultiplierForWeeks(8)).toBe(1.5);
    // 180 min at 8-week streak: floor(0.5 × 180 × 1.5) = 135
    expect(canonicalSessionRewards(10800, 8).sylph).toBe(135);
  });

  it("sessions under 60 seconds award nothing", () => {
    const r = canonicalSessionRewards(59, 8);
    expect(r.xp).toBe(0);
    expect(r.sylph).toBe(0);
  });

  it("multiplier ladder boundaries are exact", () => {
    expect(sessionMultiplierForSeconds(1799)).toBe(1.0);
    expect(sessionMultiplierForSeconds(1800)).toBe(1.1); // 30m
    expect(sessionMultiplierForSeconds(3599)).toBe(1.1);
    expect(sessionMultiplierForSeconds(3600)).toBe(1.2); // 60m
    expect(sessionMultiplierForSeconds(7199)).toBe(1.2);
    expect(sessionMultiplierForSeconds(7200)).toBe(1.3); // 120m
  });
});

/* ═══════════════════════════════════════════════════════════
   Route-level — unified atomic settlement + final-flag plumbed to RPC
   (wall-clock clamping now lives inside settle_study_session_atomic)
   ═══════════════════════════════════════════════════════════ */
describe("PATCH /api/sessions — unified settle pipeline", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(auth.verifyToken).mockResolvedValue({ userId: 1 } as any);
  });

  function authedPatch(body: unknown) {
    return new NextRequest("http://localhost/api/sessions", {
      method: "PATCH",
      headers: { "Content-Type": "application/json", Authorization: "Bearer t" },
      body: JSON.stringify(body),
    });
  }

  function settleMock(final: boolean, durationSeconds: number) {
    return [
      {
        settle_study_session_atomic: {
          success: true,
          sessionId: 5,
          isFinal: final,
          alreadyClaimed: false,
          durationSeconds,
          breakSeconds: 0,
          deltaSeconds: durationSeconds,
          awarded: final && durationSeconds >= 60,
          xpGained: 0,
          sylphGained: 0,
          totalSylphEarned: 0,
          questCompleted: false,
          questXp: 0,
          questSylph: 0,
          hpHealed: 0,
          level: 1,
          currentXP: 0,
          xpToNextLevel: 282,
          hunterRank: "E",
          levelsGained: 0,
          didRankUp: false,
          nodeProgress: null,
          masteryGranted: false,
        },
      },
    ];
  }

  it("passes the claimed duration and final=true to the unified settle RPC", async () => {
    const rpcSpy = vi
      .spyOn(prisma, "$queryRaw")
      .mockResolvedValue(settleMock(true, 7200) as any);

    // Weekly-milestone dependencies (aggregate < 180 min → no streak write)
    vi.spyOn(prisma.user, "findUnique").mockResolvedValue({
      id: 1,
      timezone: "UTC",
      lastActiveDate: "2026-W01",
      streakDays: 0,
      level: 1,
    } as any);
    vi.spyOn(prisma.studySession, "aggregate").mockResolvedValue({
      _sum: { durationMinutes: 10 },
    } as any);

    // Client claims 2 hours (7200s) — the route no longer pre-clamps; the
    // wall-clock clamp runs inside the RPC against the locked session row.
    const res = await patchSession(
      authedPatch({ id: 5, durationMinutes: 120, durationSeconds: 7200, final: true })
    );

    expect(res.status).toBe(200);

    // Template-literal call: (strings, userId, id, seconds, breakSeconds,
    // questId, subjectId, completeQuest, final, userLocalDate)
    const args = rpcSpy.mock.calls[0] as unknown[];
    expect(args[1]).toBe(1); // userId
    expect(args[2]).toBe(5); // sessionId
    expect(args[3]).toBe(7200); // claimed seconds (RPC clamps internally)
    expect(args[4]).toBe(0); // breakSeconds (no breaks on this flush)
    expect(args[5]).toBe(null); // questId
    expect(args[6]).toBe(null); // subjectId (session row already owns it)
    expect(args[7]).toBe(false); // completeQuest
    expect(args[8]).toBe(true); // final flag → single canonical award point
    expect(args[9]).toEqual(expect.any(String)); // user-local date

    const data = await res.json();
    expect(data.questCompletedNow).toBe(false);
  });

  it("marks non-final checkpoint flushes with final=false", async () => {
    const rpcSpy = vi
      .spyOn(prisma, "$queryRaw")
      .mockResolvedValue(settleMock(false, 180) as any);

    vi.spyOn(prisma.user, "findUnique").mockResolvedValue({
      id: 1,
      timezone: "UTC",
      lastActiveDate: "2026-W01",
      streakDays: 0,
      level: 1,
    } as any);
    vi.spyOn(prisma.studySession, "aggregate").mockResolvedValue({
      _sum: { durationMinutes: 3 },
    } as any);

    const res = await patchSession(
      authedPatch({ id: 5, durationMinutes: 3, durationSeconds: 180 })
    );

    expect(res.status).toBe(200);
    const args = rpcSpy.mock.calls[0] as unknown[];
    expect(args[3]).toBe(180);
    expect(args[8]).toBe(false); // auto-save flush: no reward award, no endedAt
  });
});

/* ═══════════════════════════════════════════════════════════
   POST /api/sessions — validation & start-RPC plumbing (T3)
   ═══════════════════════════════════════════════════════════ */
describe("POST /api/sessions — validation", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(auth.verifyToken).mockResolvedValue({ userId: 1 } as any);
  });

  function authedPost(body: unknown) {
    return new NextRequest("http://localhost/api/sessions", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer t" },
      body: JSON.stringify(body),
    });
  }

  it("returns 400 for invalid initialSeconds", async () => {
    const res = await startSession(authedPost({ initialSeconds: -5 }));
    expect(res.status).toBe(400);
  });

  it("returns 401 without a token", async () => {
    const res = await startSession(
      new NextRequest("http://localhost/api/sessions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
      })
    );
    expect(res.status).toBe(401);
  });

  it("passes subjectId and initialSeconds through to the start RPC", async () => {
    const rpcSpy = vi.spyOn(prisma, "$queryRaw").mockResolvedValue([
      {
        start_study_session: {
          id: 77,
          userId: 1,
          questId: null,
          subjectId: 3,
          durationMinutes: 0,
          durationSeconds: 0,
          focusRate: 80,
          startedAt: "2026-08-26T00:00:00.000Z",
        },
      },
    ] as any);

    const res = await startSession(authedPost({ subjectId: 3, initialSeconds: 900 }));
    expect(res.status).toBe(201);
    const args = rpcSpy.mock.calls[0] as unknown[];
    expect(args[1]).toBe(1); // userId
    expect(args[2]).toBe(null); // questId
    expect(args[3]).toBe(3); // subjectId
    expect(args[4]).toBe(900); // initialSeconds (bounded server-side by the RPC)
  });
});

/** @vitest-environment node */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { GET as getUserStats } from "@/app/api/user/stats/route";
import { GET as getQuests } from "@/app/api/quests/route";
import { GET as getFriends } from "@/app/api/friends/route";
import { GET as getProfile } from "@/app/api/profile/[username]/route";
import { prisma } from "@/lib/prisma";
import { signToken } from "@/lib/auth";
import { NextRequest } from "next/server";

// Companion lookup is unrelated to session aggregation and must not connect
// to a hosted database from these route unit tests.
vi.mock("@/lib/pixel-companion-service", () => ({ selectedCompanionsForUsers: async () => new Map() }));

describe("Study Timer Accuracy & Synchronization Tests", () => {
  const userId = 505;
  let validToken: string;

  beforeEach(async () => {
    vi.restoreAllMocks();
    validToken = await signToken({ userId, email: "hunter505@system.dev" });
  });

  describe("GET /api/user/stats - Today's Study Time Calculation", () => {
    it("accurately calculates todayStudySeconds, completedTodaySeconds and active session", async () => {
      const mockUser = {
        id: userId,
        email: "hunter505@system.dev",
        username: "hunter505",
        name: "Hunter Five",
        password: "hash",
        scholarId: "SCH-000505",
        verificationStatus: "VERIFIED",
        hunterRank: "C",
        level: 10,
        currentXP: 100,
        hp: 100,
        maxHp: 100,
        streakDays: 5,
        totalStudyMinutes: 120,
        totalStudySeconds: 7200,
        timezone: "UTC",
        hasCompletedOnboarding: true,
      };

      vi.spyOn(prisma.user, "findUnique").mockResolvedValue(mockUser as any);

      const pastStarted = new Date(Date.now() - 30 * 60 * 1000);
      const pastEnded = new Date(Date.now() - 10 * 60 * 1000);
      const activeStarted = new Date(Date.now() - 120 * 1000); // 2 min ago

      vi.spyOn(prisma.studySession, "findMany").mockResolvedValue([
        {
          durationMinutes: 20,
          durationSeconds: 1200,
          startedAt: pastStarted,
          endedAt: pastEnded,
        },
        {
          durationMinutes: 0,
          durationSeconds: 0,
          startedAt: activeStarted,
          endedAt: null, // active session
        },
      ] as any);

      const req = new NextRequest("http://localhost:3000/api/user/stats", {
        headers: { Authorization: `Bearer ${validToken}` },
      });

      const res = await getUserStats(req);
      expect(res.status).toBe(200);
      const data = await res.json();

      expect(data.completedTodaySeconds).toBe(1200);
      // The active session contributes its stored (flushed) seconds only —
      // a pre-first-flush session has 0 stored, so no heuristic inflation.
      expect(data.todayStudySeconds).toBe(1200);
      expect(data.todayStudyMinutes).toBe(20);
      expect(data.activeSessionStartedAt).toBe(activeStarted.toISOString());
    });
  });

  describe("GET /api/quests - Today's Seconds Calculation", () => {
    it("returns todaySeconds accurately alongside elapsedSeconds", async () => {
      vi.spyOn(prisma.user, "findUnique").mockResolvedValue({ timezone: "UTC" } as any);

      vi.spyOn(prisma.quest, "findMany").mockResolvedValue([
        {
          id: 1,
          userId,
          title: "Ch 1: Alkanes - Structure & Properties",
          requiredMinutes: 180,
          elapsedSeconds: 187,
          status: "IN_PROGRESS",
          difficulty: "NORMAL",
          scheduledFor: "2026-08-19",
          sessions: [
            {
              durationMinutes: 3,
              durationSeconds: 187,
              startedAt: new Date(),
              endedAt: new Date(),
            },
          ],
        },
      ] as any);

      const req = new NextRequest("http://localhost:3000/api/quests?date=2026-08-19", {
        headers: { Authorization: `Bearer ${validToken}` },
      });

      const res = await getQuests(req);
      expect(res.status).toBe(200);
      const data = await res.json();

      expect(data).toHaveLength(1);
      expect(data[0].elapsedSeconds).toBe(187);
      expect(data[0].todaySeconds).toBe(187);
    });
  });

  describe("GET /api/friends - Accurate study seconds & active sessions", () => {
    it("returns completedTodaySeconds and live todaySeconds for friends", async () => {
      const friendId = 606;
      vi.spyOn(prisma.user, "findUnique").mockResolvedValue({ timezone: "UTC" } as any);

      const pastStarted = new Date(Date.now() - 40 * 60 * 1000);
      const pastEnded = new Date(Date.now() - 10 * 60 * 1000);

      vi.spyOn(prisma.friendship, "findMany").mockResolvedValue([
        {
          id: 1,
          userId,
          friendId,
          friend: {
            id: friendId,
            name: "Study Pal",
            username: "studypal",
            hunterRank: "B",
            level: 15,
            totalStudyMinutes: 500,
            totalStudySeconds: 30000,
            lastSeenAt: new Date(),
            avatarUrl: null,
            activeAvatar: "class_scholar",
          },
        },
      ] as any);

      // The route computes today's study aggregates via grouped raw SQL
      // queries instead of loading every session row per friend.
      vi.spyOn(prisma, "$queryRaw").mockImplementation((async (...args: any[]) => {
        const template = args[0] as any;
        const sql = Array.isArray(template)
          ? template.join("?")
          : typeof template === "string"
            ? template
            : template?.strings?.join("?") ?? "";
        if (sql.includes("BlockedUser")) return [];
        if (sql.includes('SUM("durationSeconds")')) {
          return [{ userId: friendId, seconds: 1800 }];
        }
        if (sql.includes('MAX("startedAt")')) return [];
        return [];
      }) as any);

      const req = new NextRequest("http://localhost:3000/api/friends", {
        headers: { Authorization: `Bearer ${validToken}` },
      });

      const res = await getFriends(req);
      expect(res.status).toBe(200);
      const data = await res.json();

      expect(data).toHaveLength(1);
      expect(data[0].todaySeconds).toBe(1800);
      expect(data[0].completedTodaySeconds).toBe(1800);
      expect(data[0].todayMinutes).toBe(30);
      expect(data[0].isStudying).toBe(false);
    });
  });

  describe("GET /api/profile/[username] - Today's study time", () => {
    it("calculates todayStudySeconds and todayStudyMinutes for target scholar profile", async () => {
      const targetUser = {
        id: 707,
        username: "target_scholar",
        name: "Target Scholar",
        privacy: null,
        achievements: [],
        totalStudyMinutes: 600,
        totalStudySeconds: 36000,
        timezone: "UTC",
      };

      vi.spyOn(prisma.user, "findUnique").mockResolvedValue(targetUser as any);
      vi.spyOn(prisma.quest, "count").mockResolvedValue(5);
      vi.spyOn(prisma.friendship, "findFirst").mockResolvedValue(null);
      vi.spyOn(prisma.conversationParticipant, "findFirst").mockResolvedValue(null);
      vi.spyOn(prisma, "$queryRaw").mockResolvedValue([]);

      vi.spyOn(prisma.studySession, "findMany").mockResolvedValue([
        {
          durationMinutes: 45,
          durationSeconds: 2700,
          startedAt: new Date(Date.now() - 3600 * 1000),
          endedAt: new Date(Date.now() - 900 * 1000),
        },
      ] as any);

      const req = new NextRequest("http://localhost:3000/api/profile/target_scholar", {
        headers: { Authorization: `Bearer ${validToken}` },
      });

      const res = await getProfile(req, { params: Promise.resolve({ username: "target_scholar" }) });
      expect(res.status).toBe(200);
      const data = await res.json();

      expect(data.profile.todayStudySeconds).toBe(2700);
      expect(data.profile.todayStudyMinutes).toBe(45);
      expect(data.profile.completedTodaySeconds).toBe(2700);
    });
  });
});

/** @vitest-environment node */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { NextRequest } from "next/server";
import { prisma } from "@/lib/prisma";
import { signToken } from "@/lib/auth";
import * as authServer from "@/lib/auth-server";
import { GET as getSubjects } from "@/app/api/subjects/route";
import { GET as getUserStats } from "@/app/api/user/stats/route";

describe("Study Timer & Session Calculation Accuracy", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("calculates exact studied seconds without phantom ghost elapsed time for stale sessions in /api/subjects", async () => {
    vi.spyOn(prisma.user, "findUnique").mockResolvedValue({
      id: 101,
      timezone: "UTC",
    } as any);

    // Mock subject with one completed session (600s) and one unended stale session (started 3h ago)
    vi.spyOn(prisma.subject, "findMany").mockResolvedValue([
      {
        id: 1,
        name: "Physics",
        color: "#7c3aed",
        sessions: [
          {
            id: 10,
            durationSeconds: 191,
            durationMinutes: 3,
            startedAt: new Date(Date.now() - 3600 * 1000),
            endedAt: new Date(Date.now() - 3409 * 1000),
          },
          {
            id: 11,
            durationSeconds: 0,
            durationMinutes: 0,
            startedAt: new Date(Date.now() - 3 * 3600 * 1000),
            endedAt: null, // Dangling session
          },
        ],
      },
      {
        id: 2,
        name: "Test",
        color: "#3b82f6",
        sessions: [
          {
            id: 12,
            durationSeconds: 2035,
            durationMinutes: 33,
            startedAt: new Date(Date.now() - 4000 * 1000),
            endedAt: new Date(Date.now() - 1965 * 1000),
          },
        ],
      },
    ] as any);

    const sessionToken = await signToken({ userId: 101 });
    const req = new NextRequest("http://localhost/api/subjects", {
      headers: { cookie: `hunter_token=${sessionToken}` },
    });

    const res = await getSubjects(req);
    expect(res.status).toBe(200);
    const data = await res.json();

    expect(data).toHaveLength(2);
    expect(data[0].name).toBe("Physics");
    expect(data[0].todaySeconds).toBe(191); // exactly 191s (00:03:11)
    expect(data[1].name).toBe("Test");
    expect(data[1].todaySeconds).toBe(2035); // exactly 2035s (00:33:55)
  });

  it("calculates exact todayStudySeconds in /api/user/stats without accumulating unended ghost hours", async () => {
    vi.mocked(authServer.getSession).mockResolvedValue({ userId: 101 } as any);

    vi.spyOn(prisma.user, "findUnique").mockResolvedValue({
      id: 101,
      email: "user@sylf.app",
      username: "scholar",
      name: "Scholar",
      hunterRank: "E-Rank",
      level: 1,
      currentXP: 0,
      hp: 100,
      maxHp: 100,
      streakDays: 1,
      totalStudyMinutes: 36,
      totalStudySeconds: 2226,
      sylph: 100,
      timezone: "UTC",
      hasCompletedOnboarding: true,
      password: "hash",
    } as any);

    // Study sessions: 2 completed + 1 stale unended session started 4 hours ago
    vi.spyOn(prisma.studySession, "findMany").mockResolvedValue([
      {
        durationMinutes: 3,
        durationSeconds: 191,
        startedAt: new Date(Date.now() - 3600 * 1000),
        endedAt: new Date(Date.now() - 3409 * 1000),
      },
      {
        durationMinutes: 33,
        durationSeconds: 2035,
        startedAt: new Date(Date.now() - 4000 * 1000),
        endedAt: new Date(Date.now() - 1965 * 1000),
      },
      {
        durationMinutes: 0,
        durationSeconds: 0,
        startedAt: new Date(Date.now() - 4 * 3600 * 1000),
        endedAt: null, // Dangling session from 4 hours ago
      },
    ] as any);

    const req = new NextRequest("http://localhost/api/user/stats");
    const res = await getUserStats(req);
    expect(res.status).toBe(200);

    const data = await res.json();
    expect(data.completedTodaySeconds).toBe(2226); // 191 + 2035 = 2226s (37m 06s)
    expect(data.todayStudySeconds).toBe(2226); // NOT 4 hours + 37 mins!
  });

  it("ensures subject seconds sum matches total daily focus without double-counting", () => {
    const subjects = [
      { id: 1, name: "Physics", todaySeconds: 191 }, // 00:03:11
      { id: 2, name: "Test", todaySeconds: 2035 },    // 00:33:55
    ];

    const subjectsSeconds = subjects.reduce((acc, sub) => acc + (sub.todaySeconds || 0), 0);
    expect(subjectsSeconds).toBe(2226); // 00:37:06 (37 minutes 6 seconds)

    const formatTime = (seconds: number) => {
      const h = Math.floor(seconds / 3600);
      const m = Math.floor((seconds % 3600) / 60);
      const s = seconds % 60;
      return `${h.toString().padStart(2, "0")}:${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
    };

    expect(formatTime(subjectsSeconds)).toBe("00:37:06");
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { renderHook, act, waitFor } from "@testing-library/react";
import { useTimerLeadership } from "@/app/focus/hooks/useTimerLeadership";

/* Fake navigator.locks with observable hold/release semantics. */
function makeFakeLocks() {
  const held = new Set<string>();
  const request = vi.fn(
    (name: string, opts: { mode?: string; ifAvailable?: boolean } | undefined, cb: (lock: unknown) => any) => {
      if (held.has(name)) {
        if (opts?.ifAvailable) {
          cb(null);
          return Promise.resolve(null);
        }
        // blocking takeover: simulate an eventual grant when released
        return new Promise<void>((resolve) => {
          const poll = setInterval(() => {
            if (!held.has(name)) {
              clearInterval(poll);
              held.add(name);
              resolve(cb({ name }));
            }
          }, 10);
        });
      }
      held.add(name);
      const lock = { name };
      const ret = cb(lock);
      if (ret && typeof ret.then === "function") {
        ret.then(() => held.delete(name));
      } else {
        held.delete(name);
      }
      return Promise.resolve(lock);
    }
  );
  return {
    request,
    isHeld: (name: string) => held.has(name),
    prehold: (name: string) => held.add(name),
    release: (name: string) => held.delete(name),
  };
}

const CACHE_KEY = "t3-leadership-test";
const LOCK_NAME = `sylf-timer:${CACHE_KEY}`;

describe("useTimerLeadership (T3 regression)", () => {
  let fake: ReturnType<typeof makeFakeLocks>;
  let origLocks: unknown;

  beforeEach(() => {
    vi.useRealTimers();
    fake = makeFakeLocks();
    origLocks = (window.navigator as any).locks;
    Object.defineProperty(window.navigator, "locks", {
      configurable: true,
      value: fake,
    });
    localStorage.clear();
  });

  afterEach(() => {
    Object.defineProperty(window.navigator, "locks", {
      configurable: true,
      value: origLocks,
    });
  });

  it("acquires the lock and becomes primary on mount", async () => {
    const { result } = renderHook(() => useTimerLeadership(CACHE_KEY));
    await waitFor(() => expect(result.current.isPrimary).toBe(true));
    expect(fake.isHeld(LOCK_NAME)).toBe(true);
  });

  it("becomes a mirror when another tab holds the lock", async () => {
    fake.prehold(LOCK_NAME);
    const { result } = renderHook(() => useTimerLeadership(CACHE_KEY));
    await waitFor(() => expect(result.current.isPrimary).toBe(false));
    expect(fake.isHeld(LOCK_NAME)).toBe(true); // still held by the other tab
  });

  it("RELEASES the lock on unmount (no stale primary)", async () => {
    const { result, unmount } = renderHook(() => useTimerLeadership(CACHE_KEY));
    await waitFor(() => expect(result.current.isPrimary).toBe(true));
    expect(fake.isHeld(LOCK_NAME)).toBe(true);
    unmount();
    await waitFor(() => expect(fake.isHeld(LOCK_NAME)).toBe(false));
  });

  it("promotes to primary within the re-acquire window after the other tab releases", async () => {
    vi.useFakeTimers();
    fake.prehold(LOCK_NAME);
    const { result } = renderHook(() => useTimerLeadership(CACHE_KEY));
    await act(async () => {
      vi.advanceTimersByTime(800); // acquisition retries (3 × 200ms) all miss
    });
    expect(result.current.isPrimary).toBe(false);

    fake.release(LOCK_NAME);
    await act(async () => {
      vi.advanceTimersByTime(3_100); // next 3s re-acquire sweep
    });
    expect(result.current.isPrimary).toBe(true);
    expect(fake.isHeld(LOCK_NAME)).toBe(true);
  });

  it("falls back to the existing lease when Web Locks is exposed but denied", async () => {
    Object.defineProperty(window.navigator, "locks", { configurable: true, value: {
      request: vi.fn(async () => { throw new DOMException("denied", "SecurityError"); }),
    } });
    const { result } = renderHook(() => useTimerLeadership(CACHE_KEY));
    await waitFor(() => expect(result.current.isPrimary).toBe(true));
    expect(localStorage.getItem(`sylf-timer-lease:${CACHE_KEY}`)).toBeTruthy();
  });

  it("falls back to the localStorage lease when Web Locks is unavailable", async () => {
    vi.useFakeTimers();
    Object.defineProperty(window.navigator, "locks", {
      configurable: true,
      value: undefined,
    });
    // A fresh lease held by a (simulated) other tab.
    localStorage.setItem(
      `sylf-timer-lease:${CACHE_KEY}`,
      JSON.stringify({ id: "other-tab", ts: Date.now() - 100 })
    );

    const { result } = renderHook(() => useTimerLeadership(CACHE_KEY));
    expect(result.current.isPrimary).toBe(false);

    // After the other tab's lease expires (TTL 4s) the heartbeat promotes us.
    await act(async () => {
      vi.advanceTimersByTime(4_500);
    });
    expect(result.current.isPrimary).toBe(true);
    const lease = JSON.parse(localStorage.getItem(`sylf-timer-lease:${CACHE_KEY}`)!);
    expect(lease.id).not.toBe("other-tab");
  });
});

